import re
from decimal import Decimal

# Largest accepted amount, 1000000.00, expressed in cents.
MAX_AMOUNT_CENTS = 100_000_000

# Plain decimal: optional sign, one or more ASCII digits, optional fraction.
# No whitespace, no exponent, no leading "." form.
_PLAIN_DECIMAL = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def _cents_from_plain(text):
    match = _PLAIN_DECIMAL.fullmatch(text)
    if match is None:
        raise ValueError("amount must be a plain decimal string")
    sign, whole, frac = match.group(1), match.group(2), match.group(3) or ""

    # Digits after the last nonzero one are harmless trailing zeros; anything
    # left beyond the first two fractional digits is a fraction of a cent.
    frac_significant = frac.rstrip("0")
    if len(frac_significant) > 2:
        raise ValueError("amount is not exactly representable in cents")

    whole = whole.lstrip("0") or "0"
    if len(whole) > 7:
        raise ValueError("amount exceeds 1000000.00")
    cents = int(whole) * 100 + int((frac_significant + "00")[:2])

    if cents == 0:
        raise ValueError("amount must be nonzero")
    if sign == "-":
        raise ValueError("amount must not be negative")
    if cents > MAX_AMOUNT_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def amount_to_cents(value):
    """Validate an amount and return it as an integer number of cents."""
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")

    if isinstance(value, int):
        if value == 0:
            raise ValueError("amount must be nonzero")
        if value < 0:
            raise ValueError("amount must not be negative")
        if value > 1000000:
            raise ValueError("amount exceeds 1000000.00")
        return value * 100

    if isinstance(value, Decimal):
        if not value.is_finite():
            raise ValueError("amount must be finite")
        if value.is_zero():
            raise ValueError("amount must be nonzero")
        if value.is_signed():
            raise ValueError("amount must not be negative")
        # adjusted() is the exponent of the leading digit. It bounds the
        # value without any context arithmetic, and keeps the string below small.
        if value.adjusted() > 6:
            raise ValueError("amount exceeds 1000000.00")
        if value.adjusted() < -2:
            raise ValueError("amount is not exactly representable in cents")
        # format(..., "f") without a precision is exact and context-independent.
        return _cents_from_plain(format(value, "f"))

    if isinstance(value, str):
        return _cents_from_plain(value)

    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def cents_to_amount(cents):
    """Return an integer number of cents as a Decimal with exponent -2."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_amount(amount_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
EOF
