from .money import MAX_AMOUNT_CENTS, amount_to_cents, cents_to_amount, format_amount


def make_invoice(amounts):
    items = list(amounts)  # copy; the caller's input is never mutated
    total_cents = 0
    for item in items:
        total_cents += amount_to_cents(item)
        if total_cents > MAX_AMOUNT_CENTS:
            raise ValueError("total exceeds 1000000.00")
    return {"total": format_amount(cents_to_amount(total_cents)), "count": len(items)}
